class Solution {
public:
    bool isReflected(vector<vector<int>>& points) {
        set<pair<int, int>> pSet;
        int minX = INT_MAX, maxX = INT_MIN;
        for (const auto& p : points) {
            pSet.insert({p[0], p[1]});
            minX = min(minX, p[0]);
            maxX = max(maxX, p[0]);
        }
        int doubleMid = minX + maxX;
        for (const auto& p : pSet) {
            if (!pSet.count({doubleMid - p.first, p.second})) {
                return false;
            }
        }
        return true;
    }
};

class Solution {
    public boolean isReflected(int[][] points) {
        Set<String> set = new HashSet<>();
        int minX = Integer.MAX_VALUE, maxX = Integer.MIN_VALUE;
        for (int[] p : points) {
            set.add(p[0] + "#" + p[1]);
            minX = Math.min(minX, p[0]);
            maxX = Math.max(maxX, p[0]);
        }
        int doubleMid = minX + maxX;
        for (int[] p : points) {
            if (!set.contains((doubleMid - p[0]) + "#" + p[1])) {
                return false;
            }
        }
        return true;
    }
}

