var isReflected = function(points) {
    const set = new Set();
    let minX = Infinity, maxX = -Infinity;
    for (const [x, y] of points) {
        set.add(`${x}#${y}`);
        minX = Math.min(minX, x);
        maxX = Math.max(maxX, x);
    }
    const doubleMid = minX + maxX;
    for (const [x, y] of points) {
        if (!set.has(`${doubleMid - x}#${y}`)) {
            return false;
        }
    }
    return true;
};
